def render_parameter(param: inspect.Parameter) -> str:
    rendered = param.name
    if param.annotation is not inspect.Parameter.empty:
        anno = param.annotation
        if not _is_optional(anno) and param.default is None:
            anno = Optional[anno]
        rendered += ': ' + render_annotation(anno)
    if param.default is not inspect.Parameter.empty:
        rendered += ' = ...'
    return rendered


def render_signature(sig: inspect.Signature, max_line_len: Optional[int] = None, prefix: str = '') -> str:
    params = [render_parameter(param) for param in sig.parameters.values()]
    if sig.return_annotation is not inspect.Signature.empty:
        return_annotation = ' -> ' + render_annotation(sig.return_annotation)
    else:
        return_annotation = ''

    single_line = '(' + ', '.join(params) + ')' + return_annotation

    if max_line_len is None or len(single_line) <= max_line_len:
        return single_line

    inner_prefix = prefix + '    '
    lines = ['(']
    for i, param in enumerate(params):
        comma = ',' if i < len(params) - 1 else ''
        lines.append(inner_prefix + param + comma)
    lines.append(prefix + ')' + return_annotation)
    return '\n'.join(lines)


